#!/usr/bin/env node
// Fake `prusa-slicer-console` used by slicer.test.ts and slicer-worker.test.ts
// so those tests never need the real PrusaSlicer binary installed. Ignores
// nearly all of its arguments (it isn't actually slicing anything) except
// the `-o <path>` output path, which it writes a canned G-code footer to.
// Written as a plain Node script (rather than a shell script) so it runs
// identically on the Windows dev machine and any POSIX CI box -- see
// worker.ts's spawnSlicer, which spawns `.js`-suffixed SLICER_BINARY_PATH
// values via `node <script>` for exactly this reason.
//
// Controlled by an env var (inherited from the parent worker process's own
// environment, since child_process.spawn inherits process.env by default):
//   SLICER_STUB_MODE=fail  -> exits 1 without writing any output (simulates
//                             a slicer crash / bad input).
//   SLICER_STUB_MODE=hang  -> never exits (simulates a stuck slice, so the
//                             worker's own hard timeout has to kill it).
// Any other value (including unset) -> the normal success path below.

import { writeFileSync } from 'node:fs';

const args = process.argv.slice(2);
const outputIndex = args.indexOf('-o');
const outputPath = outputIndex !== -1 ? args[outputIndex + 1] : null;

const mode = process.env.SLICER_STUB_MODE;

if (mode === 'hang') {
  // Deliberately never exits -- the worker's own SLICER_TIMEOUT_SECONDS
  // wall-clock timeout is what's supposed to kill this process.
  setInterval(() => {}, 60 * 60 * 1000);
} else if (mode === 'fail') {
  process.exitCode = 1;
} else {
  const gcode = [
    '; generated by slicer-stub-binary.js for tests',
    '; filament used [g] = 12.34, 1.20',
    '; filament used [mm] = 456.70, 12.30',
    '; estimated printing time (normal mode) = 1h 23m 45s',
    '',
  ].join('\n');
  if (outputPath) {
    writeFileSync(outputPath, gcode, 'utf-8');
  }
  process.exitCode = 0;
}
